files.content:
* {
  box-sizing: border-box;
}

html,
body {
  height: 100%;
}

body {
  display: flex;
  justify-content: center;
  align-items: center;
  min-width: 650px;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
  background-image: url(https://code.s3.yandex.net/web-code/images/dotted.svg);
}

form {
  display: grid;
  gap: 20px;
  width: 600px;
  padding: 35px;
  background-color: #80d994;
}

label,
input {
  width: 100%;
}

label span {
  display: block;
  margin-bottom: 5px;
  font-weight: 800;
  font-size: 12px;
  text-transform: uppercase;
}

button {
  border: 1px solid #000;
  padding: 10px 65px;
  color: #000;
  font-family: inherit;
  font-weight: 800;
  font-size: inherit;
  text-transform: uppercase;
  background-color: #ffc802;
}

button:hover {
  box-shadow: inset 0 0 0 100px rgb(0 0 0 / 0.15);
  cursor: pointer;
}

button:focus {
  outline: 2px solid #000;
  outline-offset: 0;
}

button[disabled] {
  opacity: 0.6;
}

input {
  padding: 10px 15px;
  border: 1px solid #000;
  color: inherit;
  font-family: inherit;
  font-size: inherit;
  background-color: transparent;
}
